# Generated by Phase: IMPLEMENT | Feature: EVOL-104
"""A train stacks its changes by file (EVOL-104).

Every `docs/spec/*/increment_plan.md` the change touches (the tree on disk against the merge-base with the diff base)
is read: each `- SUB-{N}-{M}: {scope} · paths [g] · after [SUB-N-k] · concerns [c] · enables [c] · ~F files ·
~L lines · branch … · status: …` row (every field optional but the id; `[]` is an empty list; a list item may carry
`[…]` and `{a,b}`, commas split outside them; sub ids compare case-insensitively), grouped by its INC-N. Globs read by
the push gate's ruler (`common.glob_match`). Red when:

  (o) no order            an `after` names a sub its increment does not declare, or the `after` graph has a cycle.

  (a) stackable re-touch  a path glob (normalised string; overlap between two different globs is not judged) is listed
                          in two subs, neither in the other's transitive `after` closure, and the two subs' summed
                          ~files and ~lines both fit `surface.ceiling_files` / `surface.ceiling_lines` (an absent
                          estimate counts as nothing) — the two could have been one sub.
  (b) early gate          a sub `enables` a concern while a sub whose `concerns` carry it is not in its `after` closure.
And on a sub-increment branch (gates/branch.py's classifier), whatever plan changed:
  (c) ledger per sub      its diff touches a path in `train.close_ledgers` while another sub of its INC is not MERGED —
                          a ledger is written by the train-close sub only.
And on every changed plan (EVOL-115) — its `## Seam map` table (use case | handler | grant/route | integration test |
client | e2e case | sub; a client or e2e cell may say `closes: SUB-…`, a row may say `stub until SUB-…`), the row
fields `tasks [..]` / `measured [..]` and the INC line `**Ratified sub-increments:** N`:
  (d) split seam          a seam row's use case, handler or integration test path is matched by no `paths` glob of its sub.
  (e) stale stub          a seam row still says `stub until SUB-x` while SUB-x is MERGED (DC-35); a `stub until` or
                          `closes:` target the plan does not declare is red too.
  (f) not re-measured     a sub's `tasks` set differs from the set its estimate `measured`.
  (g) over the ratified   an INC declares more subs than its `Ratified sub-increments`.
And on every changed plan, each `### INC-N` section (EVOL-078):
  (h) exit criteria       its `**Acceptance` block lists no `- [ ]` item of its own; an item names no measure in
                          backticks (a scenario, an operation, a case id or a command); or a backticked scenario or
                          operation belongs to another INC's `Scenarios covered` / `Contract surface`, not its own.
  (i) surface declared    unless the plan is `slicing_strategy: monolithic`: the INC has no `Estimated surface:` with
                          `~N files` and `~N lines`, or one of its `SUB-` rows lacks them (CVP Check 21, owner RDR «1»).

A seam table is one whose header carries `use case` and `sub`; the template's placeholder row in a plan that declares
no sub is nothing to judge. Nothing to judge → `train: n/a`. `--figures` counts per INC: subs, unique paths, path-touches, re-touch, train total.
"""
from __future__ import annotations

import re
from pathlib import Path

from . import branch as branch_mod
from .common import GateFault, any_glob, clean as _clean, key
from .digests import changed_paths
from .seal import DEFAULT_SEAL_DIR, _norm_path, vcfg

PLAN_RE = re.compile(r"docs/spec/([^/]+)/increment_plan\.md")
ROW_RE = re.compile(r"(?m)^\s*-\s*\**SUB-(\d+)-(\d+)\**\s*(?::|—)(.*)$")   # the row shape of branch.declares_sub_increments
LISTS = ("paths", "after", "concerns", "enables", "tasks", "measured")
INC_RE = re.compile(r"(?m)^#{2,}\s*INC-(\d+)\b")
RATIFIED_RE = re.compile(r"\*\*Ratified sub-increments:\*\*\s*(\d+)")
SUB_ID = re.compile(r"SUB-\d+-\d+", re.I)
TARGET_RE = re.compile(r"(stub until|closes:)\s*`?(SUB-\d+-\d+)", re.I)
SEAM_COLS = ("use case", "handler", "integration test")
HEAD_RE = re.compile(r"(?m)^#{1,3}\s")
ACCEPT_RE = re.compile(r"(?m)^(?P<ind>[ \t]*)-\s*\*\*Acceptance\b.*$")
ITEM_RE = re.compile(r"^\s+-\s*\[[ xX]\]\s*(?P<text>\S.*)$")
SPAN_RE = re.compile(r"`([^`]+)`")
ESTIMATE = (re.compile(r"~\s*\d+\s*files\b"), re.compile(r"~\s*\d+\s*lines\b"))


def _list(rest: str, name: str) -> list[str]:
    """`name [a, b]`: the list ends at its own closing bracket (nested `[id]` kept); commas split only outside `[…]` and `{…}`."""
    m = re.search(rf"(?<![\w-]){name}\s*\[", rest)
    if not m:
        return []
    items, cur, depth = [], "", 0
    for ch in rest[m.end():]:
        if ch in "[{":
            depth += 1
        elif ch in "]}":
            if depth == 0 and ch == "]":
                break
            depth = max(depth - 1, 0)
        elif ch == "," and depth == 0:
            items.append(cur); cur = ""
            continue
        cur += ch
    items.append(cur)
    return [x.strip().strip("`").strip() for x in items if x.strip().strip("`").strip()]


def _sid(v: str) -> str:
    """A sub id as the plan declares it, whatever the case it is cited in."""
    return v.upper()


def _num(rest: str, unit: str) -> int:
    m = re.search(rf"~\s*(\d+)\s*{unit}\b", rest)
    return int(m.group(1)) if m else 0


def parse(text: str) -> dict[str, list[dict]]:
    """INC-N → its sub rows, in plan order."""
    incs: dict[str, list[dict]] = {}
    for m in ROW_RE.finditer(text or ""):
        n, sub, rest = m.group(1), f"SUB-{m.group(1)}-{m.group(2)}", m.group(3)
        row = {"id": sub, "m": int(m.group(2)), "files": _num(rest, "files"), "lines": _num(rest, "lines")}
        for k in LISTS:
            row[k] = list(dict.fromkeys(_norm_path(p) for p in _list(rest, k))) if k == "paths" else _list(rest, k)
        row["after"] = [_sid(x) for x in row["after"]]
        st = re.search(r"status:\s*\**\s*([A-Za-z]+)", rest)
        row["status"] = st.group(1).upper() if st else ""
        incs.setdefault(f"INC-{n}", []).append(row)
    return incs


def ratified(text: str) -> dict[str, int]:
    """INC-N → its `**Ratified sub-increments:** N` (absent → not judged)."""
    out, heads = {}, list(INC_RE.finditer(text or ""))
    for i, h in enumerate(heads):
        body = text[h.end(): heads[i + 1].start() if i + 1 < len(heads) else len(text)]
        m = RATIFIED_RE.search(body)
        if m:
            out[f"INC-{h.group(1)}"] = int(m.group(1))
    return out


def seams(text: str) -> list[dict]:
    """The `## Seam map` rows: column (lower-case header) → cell, plus `stub` (the SUB a placeholder waits for)."""
    rows, inside, header = [], False, None
    for line in (text or "").splitlines():
        if re.match(r"^#{1,6}\s", line):
            inside, header = bool(re.match(r"^#{1,6}\s*Seam map\s*$", line, re.I)), None
            continue
        if not inside or not line.strip().startswith("|"):
            header = None   # a table ends at its first non-table line; the next one brings its own header
            continue
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        if header is None:
            header = [c.lower() for c in cells]
        elif "use case" in header and "sub" in header and not all(set(c) <= set(":- ") for c in cells):
            row = dict(zip(header, cells))
            stub = re.search(r"stub until\s*`?(SUB-\d+-\d+)", line, re.I)
            row["stub"] = _sid(stub.group(1)) if stub else ""
            row["targets"] = [(w.lower(), _sid(t)) for w, t in TARGET_RE.findall(line)]
            rows.append(row)
    return rows


def live_seams(text: str) -> list[dict]:
    """The seam rows to judge: the template's placeholder row in a plan that declares no sub is nothing to judge."""
    has_subs = bool(parse(text))
    return [r for r in seams(text) if has_subs or "{{" not in r.get("sub", "")]


def _seam_path(cell: str) -> str:
    v = re.sub(r"(?i)closes:\s*SUB-\d+-\d+|stub until\s*`?SUB-\d+-\d+`?", "", cell or "").strip().strip("`*").strip()
    return "" if v.lower() in ("", "—", "-", "n/a", "none") else _norm_path(v.split()[0].strip("`"))


def judge_seams(text: str) -> list[str]:
    """Clauses (d)–(g) on one plan."""
    incs, problems = parse(text), []
    subs = {s["id"]: s for ss in incs.values() for s in ss}
    for row in live_seams(text):
        m = SUB_ID.search(row.get("sub", ""))
        sid = _sid(m.group(0)) if m else None
        uc = row.get("use case", "?")
        if sid not in subs:
            problems.append(f"seam `{uc}` names sub `{row.get('sub', '')}`, which the plan does not declare — name the sub that builds it")
        else:
            for col in SEAM_COLS:
                p = _seam_path(row.get(col, ""))
                if p and not (p in subs[sid]["paths"] or any_glob(p, subs[sid]["paths"])):
                    problems.append(f"seam `{uc}`: its {col} {p} lies outside {sid}'s paths — a use case, its handler and its integration test ship in one sub")
        for word, t in row["targets"]:
            if t not in subs:
                problems.append(f"seam `{uc}` says `{word} {t}`, which the plan does not declare — name the sub that closes it")
        st = row["stub"]
        if st and subs.get(st, {}).get("status") == "MERGED":
            problems.append(f"seam `{uc}` still says `stub until {st}`, and {st} is MERGED — wire the real producer and drop the stub")
    for s in subs.values():
        if (s["tasks"] or s["measured"]) and set(s["tasks"]) != set(s["measured"]):
            problems.append(f"{s['id']} carries tasks [{', '.join(s['tasks'])}] but its estimate measured [{', '.join(s['measured'])}] — "
                            f"re-measure the sub after routing work into it")
    for inc, n in ratified(text).items():
        if len(incs.get(inc, [])) > n:
            problems.append(f"{inc} declares {len(incs[inc])} subs, {n} ratified — re-plan the remaining work by file through the split's RDR before another sub")
    return problems


def _items(line: str) -> list[str]:
    """The `[a, b]` list of one field line: commas split outside brackets and backticks; placeholders dropped."""
    start = line.find("[")
    if start < 0:
        return []
    items, cur, depth, tick = [], "", 0, False
    for ch in line[start + 1:]:
        if ch == "`":
            tick = not tick
        elif not tick and ch in "[{(":
            depth += 1
        elif not tick and ch in "]})":
            if depth == 0:
                break
            depth -= 1
        if ch == "," and depth == 0 and not tick:
            items.append(cur); cur = ""
        else:
            cur += ch
    items.append(cur)
    return [v for v in (_measure(i) for i in items) if v and "{{" not in v]


def _measure(v: str) -> str:
    return re.sub(r"\s+", " ", v.strip().strip("`'\"").strip()).casefold()


def _field(body: str, label: str) -> list[str]:
    m = re.search(rf"\*\*{label}:\*\*([^\n]*)", body)
    return _items(m.group(1)) if m else []


def increments(text: str) -> list[dict]:
    """Each `### INC-N` section: its scenarios, operations, exit criteria, estimate and sub rows."""
    out, text = [], text or ""
    heads = list(INC_RE.finditer(text))
    for i, h in enumerate(heads):
        end = heads[i + 1].start() if i + 1 < len(heads) else len(text)
        nxt = HEAD_RE.search(text, h.end())
        body = text[h.end(): min(end, nxt.start() if nxt else end)]
        criteria = []
        acc = ACCEPT_RE.search(body)
        if acc:
            field = re.compile(rf"^[ \t]{{0,{len(acc.group('ind'))}}}-\s*\*\*")
            for line in body[acc.end():].splitlines()[1:]:
                if field.match(line):
                    break
                m = ITEM_RE.match(line)
                if m:
                    criteria.append(m.group("text").strip())
        est = re.search(r"\*\*Estimated surface:\*\*([^\n]*)", body)
        out.append({"id": f"INC-{h.group(1)}", "scenarios": set(_field(body, "Scenarios covered")),
                    "operations": set(_field(body, "Contract surface")), "criteria": criteria, "has_acceptance": bool(acc),
                    "estimate": est.group(1) if est else None,
                    "subs": [(f"SUB-{m.group(1)}-{m.group(2)}", m.group(3)) for m in ROW_RE.finditer(body)]})
    return out


def judge_exits(text: str) -> list[str]:
    """Clauses (h) and (i) on one plan."""
    incs, problems = increments(text), []
    strategy = re.search(r"(?m)^slicing_strategy:\s*\"?(\w+)", text or "")
    estimated = not (strategy and strategy.group(1).lower() == "monolithic")
    for inc in incs:
        others = [o for o in incs if o["id"] != inc["id"]]
        if not inc["criteria"]:
            problems.append(f"{inc['id']}: no exit criterion of its own under **Acceptance** — list each one, "
                            "with the measure that decides it in backticks")
        for c in inc["criteria"]:
            spans = [_measure(x) for x in SPAN_RE.findall(c)]
            short = c if len(c) <= 70 else c[:67] + "…"
            if not spans:
                problems.append(f"{inc['id']}: exit criterion «{short}» names no measure — put the scenario, operation, "
                                "case or command that decides it in backticks")
            for sp in spans:
                mine = sp in inc["scenarios"] or sp in inc["operations"]
                owner = next((o["id"] for o in others if sp in o["scenarios"] or sp in o["operations"]), None)
                if owner and not mine:
                    problems.append(f"{inc['id']}: exit criterion «{short}» measures `{sp}`, which {owner} delivers — "
                                    "an increment exits on its own criteria")
        if estimated:
            if inc["estimate"] is None or not all(r.search(inc["estimate"]) for r in ESTIMATE):
                problems.append(f"{inc['id']}: no estimated surface (`Estimated surface:` with ~N files · ~N lines) — "
                                "estimate it and split it when over the ceiling (BLUEPRINT Step B.4)")
            for sid, rest in inc["subs"]:
                if not all(r.search(rest) for r in ESTIMATE):
                    problems.append(f"{sid}: no estimated surface (~N files · ~N lines) — measure the sub against the ceiling")
    return problems


def order(subs: list[dict]) -> list[str]:
    """The `after` graph itself: a dangling target or a cycle leaves the order undefined."""
    by, problems = {s["id"]: s for s in subs}, []
    for s in subs:
        for x in s["after"]:
            if x not in by:
                problems.append(f"{s['id']} comes after {x}, which its increment does not declare — name a declared sub or drop it")
    for s in subs:
        if s["id"] in closure(subs, s["id"], with_self=True):
            problems.append(f"{s['id']} comes after itself through `after` (a cycle) — break the cycle so the train has an order")
    return problems


def closure(subs: list[dict], sid: str, with_self: bool = False) -> set[str]:
    """The transitive `after` closure of one sub (itself only when `with_self` or a cycle returns to it)."""
    by = {s["id"]: s for s in subs}
    seen: set[str] = set()
    todo = list(by.get(sid, {}).get("after", []))
    while todo:
        x = todo.pop()
        if x in seen or (x == sid and not with_self):
            continue
        seen.add(x)
        todo += by.get(x, {}).get("after", [])
    return seen


def judge(subs: list[dict], ceiling_files: int, ceiling_lines: int) -> list[str]:
    """Clauses (a) and (b) on one increment's subs."""
    problems = order(subs)
    clo = {s["id"]: closure(subs, s["id"]) for s in subs}
    for i, s in enumerate(subs):
        for t in subs[i + 1:]:
            shared = [p for p in s["paths"] if p in t["paths"]]
            if not shared or t["id"] in clo[s["id"]] or s["id"] in clo[t["id"]]:
                continue
            files, lines = s["files"] + t["files"], s["lines"] + t["lines"]
            if files <= ceiling_files and lines <= ceiling_lines:
                problems.append(f"{s['id']} and {t['id']} both touch {', '.join(shared)}, neither comes after the other, and together "
                                f"(~{files} files, ~{lines} lines) they fit the ceiling ({ceiling_files} files, {ceiling_lines} lines) — "
                                f"stack them into one sub, or order them with `after`")
    for s in subs:
        for c in s["enables"]:
            early = [t["id"] for t in subs if t["id"] != s["id"] and c in t["concerns"] and t["id"] not in clo[s["id"]]]
            if early:
                problems.append(f"{s['id']} turns on the gate for `{c}` before {', '.join(early)}, which still carries it — "
                                f"list {', '.join(early)} in its `after`")
    return problems


def _plans(repo: Path, changed: set[str]) -> list[str]:
    return sorted(c for c in changed if PLAN_RE.fullmatch(c) and (repo / c).is_file())


def _read(repo: Path, rel: str) -> str:
    return (repo / rel).read_text(encoding="utf-8", errors="replace")


def ledger(repo: Path, branch: str | None, changed: set[str]) -> dict | None:
    """Clause (c): None when the branch is not a sub-increment."""
    try:
        info = branch_mod.branch_class(repo, branch)
    except GateFault:
        return None
    if info["class"] != "sub-increment":
        return None
    m = branch_mod.INC_RE.match(info["branch"])
    me, inc = f"SUB-{m.group('n')}-{m.group('m')}", f"INC-{m.group('n')}"
    ledgers = [_norm_path(p) for p in (key(repo, "train.close_ledgers", default=[]) or [])]
    touched = sorted(p for p in ledgers if p in changed)
    plan = f"docs/spec/{m.group('id')}/increment_plan.md"
    if not touched:
        return {"id": me, "ok": True, "problems": [], "note": "touches no ledger of `train.close_ledgers`" if ledgers else "no `train.close_ledgers` key — nothing to hold to the train close"}
    if not (repo / plan).is_file():
        return {"id": me, "ok": True, "problems": [], "note": f"writes {', '.join(touched)}; no increment plan at {plan} declares a sibling sub to wait for"}
    subs = parse(_read(repo, plan)).get(inc, [])
    open_ = [s["id"] for s in subs if s["id"] != me and s["status"] != "MERGED"]
    if not open_:
        return {"id": me, "ok": True, "problems": [], "note": f"the train-close sub writes {', '.join(touched)}"}
    return {"id": me, "ok": False, "note": "", "problems": [
        f"writes {', '.join(touched)} while {', '.join(open_)} of {inc} is not MERGED — a ledger is written once per train, by the train-close sub; move the write there"]}


def check(repo: Path, base: str, branch: str | None = None) -> dict:
    try:
        cfg = vcfg(repo)
    except GateFault:
        cfg = {"dir": DEFAULT_SEAL_DIR}
    changed = {_norm_path(c) for c in changed_paths(repo, base, cfg)}
    plans = _plans(repo, changed)
    rows = []
    if plans:
        cf = int(key(repo, "surface.ceiling_files", required=True))
        cl = int(key(repo, "surface.ceiling_lines", required=True))
        for plan in plans:
            for inc, subs in parse(_read(repo, plan)).items():
                problems = judge(subs, cf, cl)
                rows.append({"id": f"{PLAN_RE.fullmatch(plan).group(1)} {inc}", "ok": not problems, "problems": problems, "note": f"{len(subs)} sub(s) stacked by file"})
            text = _read(repo, plan)
            if increments(text):
                problems = judge_exits(text)
                rows.append({"id": f"{PLAN_RE.fullmatch(plan).group(1)} exits", "ok": not problems, "problems": problems,
                             "note": f"{len(increments(text))} increment(s): exit criteria measurable on their own, every surface estimated"})
            if live_seams(text) or ratified(text) or any(s["tasks"] or s["measured"] for ss in parse(text).values() for s in ss):
                problems = judge_seams(text)
                rows.append({"id": f"{PLAN_RE.fullmatch(plan).group(1)} seams", "ok": not problems, "problems": problems,
                             "note": "seams in one sub, no stale stub, every routing re-measured, within the ratified count"})
    led = ledger(repo, branch, changed)
    if led:
        rows.append(led)
    if not rows:
        why = "the change's increment plan(s) declare no sub-increment" if plans else "no increment plan in the change (docs/spec/*/increment_plan.md) and not a sub-increment branch"
        return {"ok": True, "plans": plans, "entries": [], "reason": f"{why} — nothing to judge"}
    red = [r for r in rows if not r["ok"]]
    return {"ok": not red, "plans": plans, "entries": rows,
            "reason": f"{len(red)} of {len(rows)} check(s) red" if red else f"{len(rows)} check(s) green — the train stacks by file"}


def figures(repo: Path, plan: str | None = None) -> dict:
    """Per INC: subs (rounds paid), unique paths, path-touches, re-touch (touches − unique)."""
    plans = [_norm_path(plan)] if plan else sorted(str(p.relative_to(repo)) for p in (repo / "docs/spec").glob("*/increment_plan.md"))
    out = []
    for p in plans:
        if not (repo / p).is_file():
            raise GateFault(f"no increment plan at {p}")
        for inc, subs in parse(_read(repo, p)).items():
            touches = sum(len(s["paths"]) for s in subs)
            unique = len({x for s in subs for x in s["paths"]})
            out.append({"plan": p, "inc": inc, "subs": len(subs), "unique_paths": unique, "path_touches": touches, "retouch": touches - unique,
                        "total_files": sum(s["files"] for s in subs), "total_lines": sum(s["lines"] for s in subs)})
    return {"ok": True, "figures": out}


def render(res: dict) -> str:
    if "figures" in res:
        if not res["figures"]:
            return "train: n/a — no increment plan declares sub-increments"
        return "\n".join(_clean(f"train: {f['plan']} {f['inc']} — subs {f['subs']} · unique paths {f['unique_paths']} · "
                                f"path-touches {f['path_touches']} · re-touch {f['retouch']} · "
                                f"train total ~{f['total_files']} files ~{f['total_lines']} lines") for f in res["figures"])
    if not res.get("entries"):
        return _clean(f"train: {'n/a' if res['ok'] else 'RED'} — {res['reason']}")
    lines = [f"train: {'ok' if res['ok'] else 'RED'} — {res['reason']} ({', '.join(res['plans']) or 'no increment plan changed'})"]
    for r in res["entries"]:
        lines.append(f"  {'✓' if r['ok'] else '✗'} {r['id']}: {'; '.join(r['problems']) or r['note']}")
    return "\n".join(_clean(ln) for ln in lines)
